using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-d06bab089cc64dc981e35121f6f4db04/build.binlog");

// Get the actual source file content from the compiler command line
Console.WriteLine("=== Looking for source content ===");
var allNodes = build.FindChildrenRecursive<CscCommandLineArgs>();
foreach (var node in allNodes) {
    Console.WriteLine($"CSC args found");
}

// Try SourceFilesFromCompiler
var tasks = build.FindChildrenRecursive<Task>();
foreach (var t in tasks)
{
    if (t.Name == "Csc")
    {
        Console.WriteLine($"\nCsc task in project context:");
        var parent = t.Parent;
        while (parent != null) {
            if (parent is Project proj) { Console.WriteLine($"  Project: {proj.Name}"); break; }
            parent = parent.Parent;
        }
        // print children types
        foreach (var child in t.Children.Take(5))
            Console.WriteLine($"  Child: {child.GetType().Name} - {child}");
    }
}

// Look for Api build result - did it fail because of Services?
Console.WriteLine("\n=== Build messages ===");
var allMessages = build.FindChildrenRecursive<AbstractDiagnostic>();
foreach (var m in allMessages)
{
    if (m is Error || (m.Text != null && m.Text.Contains("MSB")))
        Console.WriteLine($"  [{m.GetType().Name}] {m.Code}: {m.Text?.Substring(0, Math.Min(150, m.Text.Length))}");
}
EOF
